import { Component, OnInit, OnDestroy } from '@angular/core';
import { Router } from '@angular/router';
import { CartService } from 'src/app/services/cart.service';
import { Cart, CartItem } from 'src/app/models/cart.model';
import { Subscription } from 'rxjs';

@Component({
  selector: 'app-my-cart',
  templateUrl: './my-cart.component.html',
  styleUrls: ['./my-cart.component.css'],
})
export class MyCartComponent implements OnInit, OnDestroy {
  cart: Cart = { items: [], totalAmount: 0, totalItems: 0 };
  private cartSubscription: Subscription = new Subscription();

  constructor(
    private cartService: CartService,
    private router: Router,
  ) {}

  ngOnInit(): void {
    this.cartSubscription = this.cartService
      .getCartObservable()
      .subscribe((cart) => {
        this.cart = cart;
      });
  }

  ngOnDestroy(): void {
    if (this.cartSubscription) {
      this.cartSubscription.unsubscribe();
    }
  }

  updateQuantity(item: CartItem, newQuantity: number): void {
    if (newQuantity < 1) {
      this.removeItem(item);
    } else {
      this.cartService.updateQuantity(item.id, newQuantity);
    }
  }

  removeItem(item: CartItem): void {
    if (confirm(`Remove ${item.name} from cart?`)) {
      this.cartService.removeFromCart(item.id);
    }
  }

  clearCart(): void {
    if (confirm('Are you sure you want to clear your entire cart?')) {
      this.cartService.clearCart();
    }
  }

  proceedToCheckout(): void {
    if (this.cart.items.length === 0) {
      alert('Your cart is empty!');
      return;
    }

    // Store cart for checkout
    localStorage.setItem('checkout_cart', JSON.stringify(this.cart));
    this.router.navigate(['/checkout']);
  }

  continueShopping(): void {
    this.router.navigate(['/user/items']);
  }

  formatPrice(price: number): string {
    return price.toLocaleString('en-IN');
  }

  getImageUrl(imageUrl: string): string {
    if (!imageUrl) {
      return 'https://via.placeholder.com/100x100/667eea/ffffff?text=Product';
    }
    if (imageUrl.startsWith('http')) {
      return imageUrl;
    }
    return 'http://localhost:8080/api/user/items/images/' + imageUrl;
  }

  onImageError(event: any): void {
    event.target.src =
      'https://via.placeholder.com/100x100/ff6b6b/ffffff?text=Image+Not+Found';
  }
}
<div class="cart-container">
  <div class="cart-header">
    <h1>🛒 My Cart</h1>
    <p>Review and manage your items</p>
  </div>

  <!-- Empty Cart -->
  <div class="empty-cart" *ngIf="cart.items.length === 0">
    <div class="empty-icon">🛒</div>
    <h2>Your Cart is Empty</h2>
    <p>Looks like you haven't added any items to your cart yet.</p>
    <button class="shop-now-btn" (click)="continueShopping()">
      Continue Shopping
    </button>
  </div>

  <!-- Cart with items -->
  <div class="cart-content" *ngIf="cart.items.length > 0">
    <div class="cart-items">
      <div class="cart-item" *ngFor="let item of cart.items">
        <div class="item-image">
          <img
            [src]="getImageUrl(item.imageUrl)"
            [alt]="item.name"
            (error)="onImageError($event)"
          />
        </div>

        <div class="item-details">
          <h3>{{ item.name }}</h3>
          <p class="item-price">₹{{ formatPrice(item.price) }}</p>
        </div>

        <div class="item-quantity">
          <button
            class="qty-btn"
            (click)="updateQuantity(item, item.quantity - 1)"
          >
            -
          </button>
          <span class="qty-value">{{ item.quantity }}</span>
          <button
            class="qty-btn"
            (click)="updateQuantity(item, item.quantity + 1)"
          >
            +
          </button>
        </div>

        <div class="item-total">
          <span>Total:</span>
          <strong>₹{{ formatPrice(item.total) }}</strong>
        </div>

        <button class="remove-btn" (click)="removeItem(item)" title="Remove">
          🗑️
        </button>
      </div>
    </div>

    <!-- Cart Summary -->
    <div class="cart-summary">
      <h2>Order Summary</h2>

      <div class="summary-row">
        <span>Total Items:</span>
        <span>{{ cart.totalItems }}</span>
      </div>

      <div class="summary-row">
        <span>Total Amount:</span>
        <span class="total-amount">₹{{ formatPrice(cart.totalAmount) }}</span>
      </div>

      <div class="summary-row">
        <span>Delivery Charges:</span>
        <span *ngIf="cart.totalAmount > 999" class="free">Free</span>
        <span *ngIf="cart.totalAmount <= 999" class="delivery-charge">₹50</span>
      </div>

      <div class="summary-row grand-total" *ngIf="cart.totalAmount <= 999">
        <span>Grand Total:</span>
        <span>₹{{ formatPrice(cart.totalAmount + 50) }}</span>
      </div>

      <div class="delivery-info" *ngIf="cart.totalAmount < 999">
        <span class="info-icon">🚚</span>
        <span
          >Add ₹{{ formatPrice(999 - cart.totalAmount) }} more for FREE
          Delivery</span
        >
      </div>

      <div class="delivery-info free-delivery" *ngIf="cart.totalAmount >= 999">
        <span class="info-icon">🎉</span>
        <span>Congratulations! You get FREE Delivery</span>
      </div>

      <div class="action-buttons">
        <button class="clear-btn" (click)="clearCart()">Clear Cart</button>
        <button class="checkout-btn" (click)="proceedToCheckout()">
          Proceed to Checkout
        </button>
      </div>

      <button class="continue-btn" (click)="continueShopping()">
        ← Continue Shopping
      </button>
    </div>
  </div>
</div>
